mapper.sql:
WHERE tenant_id = #{tenantId}
  AND kind = #{kind}
  AND del_flag = 0

  AND (
    asset_name LIKE CONCAT('%', #{keyword}, '%')
    OR asset_key LIKE CONCAT('%', #{keyword}, '%')
    OR IFNULL(source_file_name, '') LIKE CONCAT('%', #{keyword}, '%')
  )

mapper.select:
SELECT 
FROM sys_content_installed_asset
WHERE tenant_id = #{tenantId}
  AND kind = #{kind}
  AND asset_key = #{assetKey}
  AND del_flag = 0
LIMIT 1

SELECT 
FROM sys_content_installed_asset
WHERE tenant_id = #{tenantId}
  AND id = #{id}
  AND del_flag = 0
LIMIT 1
